#include <iostream>
using namespace std;

const int MAXN = 1000005;
int a[MAXN];

int main() {
    int n;
    if (!(cin >> n)) return 0;
    for (int i = 0; i < n; i++) cin >> a[i];

    long long best = a[0];
    long long endingHere = a[0];
    for (int i = 1; i < n; i++) {
        if (endingHere > 0) endingHere += a[i];
        else endingHere = a[i];
        if (endingHere > best) best = endingHere;
    }
    cout << best << "\n";
    return 0;
}
